import{_ as r,I as a,o as n,c as i,j as o,a as t,J as c,ak as l}from"./chunks/framework.D6lxc04_.js";const x=JSON.parse('{"title":"Rendering 渲染","description":"","frontmatter":{"title":"Rendering 渲染","prev":false,"next":false},"headers":[],"relativePath":"posts/docs/rendering/index.md","filePath":"posts/docs/rendering/index.md","lastUpdated":1778164797000}'),s={name:"posts/docs/rendering/index.md"},f={id:"渲染模块",tabindex:"-1"};function h(p,e,m,b,g,u){const d=a("Badge");return n(),i("div",null,[o("h1",f,[e[0]||(e[0]=t("渲染模块 ",-1)),c(d,{type:"tip",text:"26.1 only"}),e[1]||(e[1]=t()),e[2]||(e[2]=o("a",{class:"header-anchor",href:"#渲染模块","aria-label":"Permalink to “渲染模块”"},"​",-1))]),e[3]||(e[3]=l('<blockquote><p><strong>可用性</strong>: 本模块<strong>仅</strong>在 Minecraft <strong>26.1</strong> 版本中存在。所有更早的版本（1.21.1 至 1.21.11）均不包含此模块。</p></blockquote><p>包 <code>dev.anvilcraft.lib.v2.rendering</code> 提供了泛光（Bloom）后处理效果以及一套通用的 UBO（Uniform Buffer Object）布局定义框架，并通过 Mixin 集成到 Minecraft 的 GUI 渲染和主渲染流程中。</p><h2 id="文档索引" tabindex="-1">文档索引 <a class="header-anchor" href="#文档索引" aria-label="Permalink to “文档索引”">​</a></h2><table tabindex="0"><thead><tr><th>文档</th><th>内容</th></tr></thead><tbody><tr><td><a href="./bloom.html">泛光后处理</a></td><td><code>BloomPostEffect</code>、<code>BloomRenderCallback</code>、多 Pass 处理链</td></tr><tr><td><a href="./ubo.html">UBO 框架</a></td><td><code>UboObject</code>、<code>UboLayoutDefinition</code>、<code>UboLayoutEntry</code>、STD140 布局</td></tr><tr><td><a href="./integration.html">渲染集成</a></td><td><code>ALRendering</code>、Mixin、<code>LibGuiElementRenderState</code>、着色器管线</td></tr><tr><td><a href="./sdf.html">SDF 2D 图形</a></td><td><code>SdfGraphics</code>、<code>Sdf2d</code>、<code>SdfParameters</code>、7 种图形类型</td></tr></tbody></table><h2 id="模块结构" tabindex="-1">模块结构 <a class="header-anchor" href="#模块结构" aria-label="Permalink to “模块结构”">​</a></h2><ul><li><strong>主类</strong>: <code>ALRendering</code> — 模组入口，创建管线，注册事件</li><li><strong>后处理</strong>: <code>BloomPostEffect</code> — 泛光效果多 Pass 处理链</li><li><strong>UBO 框架</strong>: <code>foundation.ubo</code> 包 — 类型安全的 ST140 布局定义</li><li><strong>着色器</strong>: <code>blit.vsh</code>, <code>blur.fsh</code>, <code>apply_bloom.fsh</code>, <code>down_sample.fsh</code>, <code>up_sample.fsh</code></li><li><strong>Mixin</strong>: <code>GuiRendererMixin</code>, <code>MinecraftMixin</code> — 渲染流程嵌入</li></ul><blockquote><p>该模块仅在 Minecraft 26.1 版本中存在（<code>module.rendering</code>）。</p></blockquote><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to “注意事项”">​</a></h2><ul><li>泛光效果依赖大量 RenderTarget 创建，限定客户端环境</li><li>所有 GPU 资源由 <code>GpuDevice</code> 创建，生命周期跟随 <code>BloomPostEffect</code> 实例</li><li>Mixin 修改 <code>GuiRenderer</code> 内部行为，可能与其它渲染模组冲突</li></ul>',9))])}const P=r(s,[["render",h]]);export{x as __pageData,P as default};
